{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "ThH, a steroidal analogue with the highest transfer score, is reported to have very low oral bioavailability in humans, directly supporting a low F prediction for the query's steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Abiraterone, a steroidal drug, has estimated absolute oral bioavailability <10% in humans in the fasted state, providing direct quantitative evidence below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Testosterone undecanoate, a lipophilic steroid ester, has an absolute oral bioavailability of 6.83 ± 3.32% in humans, showing that even lipophilic steroid prodrugs can have low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "β-Sitosterol, a sterol with a similar fused-ring system, has an absolute oral bioavailability of 0.41% in humans, demonstrating extremely low F for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Danazol in the fasted state has an absolute bioavailability of 13%, below the 20% threshold, indicating that fasted-state oral absorption of steroids is often low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Danazol in the fed state as an emulsion reaches 67% absolute bioavailability, but this is formulation- and fed-state-dependent and not transferable to the polar, hydroxylated query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a polar, hydroxylated steroid; multiple high-transfer steroid analogues show absolute oral bioavailability below 20% (abiraterone <10%, testosterone undecanoate 6.8%, β-sitosterol 0.41%, danazol fasted 13%). The only high value (danazol fed 67%) is formulation-dependent and not applicable. Therefore, predict low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "The exact identity and physicochemical properties of the query were not fully analyzed; however, its multiple hydroxyl groups suggest high polarity and likely poor permeability.",
    "Fed-state high bioavailability of danazol is not transferable to the query due to formulation dependence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

